  $row('air3','Air 3',82,8064,6048,'https://www.dji.com/air-3/specs'),
  $row('air3s','Air 3S',84,8192,6144,'https://www.dji.com/air-3s/specs'),
  $row('mavic3','Mavic 3 Series · Hauptkamera',84,5280,3956,'https://www.dji.com/mavic-3/specs'),
