function dm_plan_osm_xml(string $raw): array {
 $xml=dm_xml($raw);$nodes=[];foreach($xml->node as $n){$lat=dm_num((string)$n['lat']);$lng=dm_num((string)$n['lon']);if($lat!==null&&$lng!==null)$nodes[(string)$n['id']]=['lat'=>$lat,'lon'=>$lng];}
