}

/* Repeat the last capture points with their intervening navigation points. */
function dm_plan_repeat(array $chunk,int $n): array {
 $start=count($chunk);for($i=count($chunk)-1;$i>=0;$i--)if($chunk[$i]['capture']??true){$start=$i;if(--$n===0)break;}
